        require(address(this).balance >= amount);
        require(amount > 0);

        address originalOwner = c.owner(); if (__ESBMC_reverted()) return;
        uint ownerBalanceBefore = originalOwner.balance;
        uint cBalanceBefore = address(c).balance;

        bool reverted;
        c.go{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
