        vm.assume(address(this).balance >= amount);
        vm.assume(amount > 0);
        address originalOwner;
        try c.owner() returns (address __r) { originalOwner = __r; } catch { return; }
        uint ownerBalanceBefore = originalOwner.balance;
        uint cBalanceBefore = address(c).balance;
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
